#!/usr/bin/env python3
"""Refuse pull requests from non-maintainers that touch first-party namespaces.

Reads changed paths (new and previous names) on stdin. Arguments: the author's
`author_association` and whether the PR branch lives in this repository.
shortcut: a PR can edit this workflow, so real enforcement is a required code-owner
review; this check only fails fast.
"""

import re
import sys

# index.json is generated by the publisher, so any non-maintainer edit is refused.
RESERVED = re.compile(r"(?:(?:pack-sources|packs)/(?:mvm|agent|runtime)/|index\.json\Z)")
TRUSTED = {"OWNER", "MEMBER", "COLLABORATOR"}
FILES_API_LIMIT = 3000  # the PR files endpoint silently stops listing here


def violations(paths, association, same_repo=False):
    # A branch in this repository can only be pushed by someone with write access, which
    # is what "maintainer" means here. author_association alone is unreliable: the Actions
    # token cannot see private organisation membership and reports MEMBER as CONTRIBUTOR.
    if same_repo or association in TRUSTED:
        return []
    return [path for path in paths if RESERVED.match(path)]


def unverifiable(paths, changed_files):
    """Why the listing cannot prove a PR is clear of reserved paths, or None."""
    if not paths:
        return "the changed-file listing is empty"
    if changed_files >= FILES_API_LIMIT:
        return f"the PR changes {changed_files} files, more than the {FILES_API_LIMIT} the listing can show"
    return None


if __name__ == "__main__":
    paths = sys.stdin.read().split()
    association = sys.argv[1] if len(sys.argv) > 1 else "NONE"
    same_repo = len(sys.argv) > 2 and sys.argv[2] == "true"
    changed_files = int(sys.argv[3]) if len(sys.argv) > 3 else 0
    # Fail closed: a failed or truncated listing must not read as "no violations".
    if not (same_repo or association in TRUSTED) and (reason := unverifiable(paths, changed_files)):
        sys.exit(f"cannot verify first-party namespaces: {reason}; a maintainer must review")
    bad = violations(paths, association, same_repo)
    if bad:
        sys.exit("first-party namespaces (mvm, agent, runtime) need a maintainer:\n  " + "\n  ".join(bad))
